1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>} where
11	 * LAST3 is the upper-cased first three letters of the last name and NNNN is a global
12	 * 4-digit zero-padded sequence equal to one more than the current number of owners
13	 * (e.g. {@code SMI-0007}). Runs before the owner is saved, so the count reflects the
14	 * existing owners only.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String lastName = owner.getLastName();
20	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
21	        int sequence = ownerRepository.findAll().size() + 1;
22	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
23	    }
24	}
